#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int MAXN = 32;
const int MAXB = 60;
const int MOD = 1000000007;
const ll INF = 2000000000000000000LL;

inline void fix(int &x)
{
    if (x >= MOD) x -= MOD;
    if (x < 0) x += MOD;
}

struct Mat
{
    int v[MAXN][MAXN];
    int n;
    Mat(int size=0, int fill=0)
    {
        n = size;
        for (int i=0; i<n; i++)
            for (int j=0; j<n; j++)
                v[i][j] = (i==j)? fill : 0;
    }
    int* operator[](int i) { return v[i]; }
    Mat operator*(const Mat &b)
    {
        Mat res(n,0);
        for (int i=0; i<n; i++)
            for (int j=0; j<n; j++)
                for (int k=0; k<n; k++)
                    fix(res[i][k] += (ll)v[i][j] * b[j][k] % MOD);
        return res;
    }
    Mat operator+(const Mat &b)
    {
        Mat res(n,0);
        for (int i=0; i<n; i++)
            for (int j=0; j<n; j++)
                res[i][j] = v[i][j] + b[i][j];
        return res;
    }
    bool operator==(const Mat &b)
    {
        if (n != b.n) return false;
        for (int i=0; i<n; i++)
            for (int j=0; j<n; j++)
                if (v[i][j] != b[i][j]) return false;
        return true;
    }
};

Mat mat_pow(Mat base, ll exp)
{
    Mat result(base.n,1);
    while (exp)
    {
        if (exp & 1) result = result * base;
        base = base * base;
        exp >>= 1;
    }
    return result;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    ll n;
    int k;
    cin >> n >> k;

    vector<ll> val(MAXB, 1);
    int lastIdx = MAXB;
    for (int i=1; i<MAXB; i++)
    {
        if (val[i-1] >= INF / k)
        {
            val[i] = INF;
            lastIdx = i;
            break;
        }
        val[i] = val[i-1] * k;
    }

    vector<Mat> shift(MAXB, Mat(k+1));
    shift[0] = Mat(k+1, 1);
    shift[1] = Mat(k+1);
    for (int i=0; i<k; i++)
        shift[1][i][(i-1+k)%k] = 1;
    shift[1][k][k] = 1;

    for (int i=2; i<k; i++)
        shift[i] = shift[i-1] * shift[1];

    vector<Mat> a(MAXB, Mat(k+1));
    for (int i=0; i<=k; i++)
        a[0][i][0] = 1;

    for (int i=1; i<lastIdx; i++)
    {
        Mat tmp = a[i-1];
        a[i] = a[i-1];
        for (int j=1; j<k; j++)
        {
            a[i] = a[i] * shift[k-1];
            a[i] = a[i] * tmp;
        }
        a[i] = a[i] * shift[k-1];
    }

    Mat ans(k+1);
    ans[0][k] = 1;
    ans = ans * get(n, lastIdx - 1);

    int res = 0;
    for (int i=0; i<=k; i++)
        fix(res += ans[0][i]);

    cout << res << "\n";
}
